function main(input) {
  const level = input.amount >= 100000 ? "部長" : "課長";
  const hit = (input.approvers || []).find(a => a.data && a.data.level === level);
  if (!hit) throw new Error("承認者（" + level + "）が承認者の表にいません");
  return { name: hit.data.name, level: level };
}

