function main(input) {
  const map = {};
  for (const it of (input.items || [])) {
    const d = it.data || {};
    const rep = d.rep || '(担当者未設定)';
    if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0, notes: [] };
    map[rep].visits += Number(d.visits || 0);
    map[rep].prospect += Number(d.prospect || 0);
    if (d.note) map[rep].notes.push((d.report_date || '') + ': ' + d.note);
  }
  const reps = Object.values(map).sort((a, b) => (a.rep < b.rep ? -1 : 1));
  const rows = reps.map(r => ({ week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const digest = reps.map(r => '担当者: ' + r.rep + '\n訪問件数合計: ' + r.visits + '\n見込み額合計: ' + r.prospect + '\n所感:\n' + (r.notes.length ? r.notes.map(n => '- ' + n).join('\n') : '- なし')).join('\n\n');
  return { rows: rows, digest: digest };
}

function main(input) {
  const sums = {};
  for (const it of input.items ?? []) {
    const d = it.data ?? {};
    const rep = d.rep ?? '(未記入)';
    if (!sums[rep]) sums[rep] = { rep: rep, visits: 0, prospect: 0 };
    sums[rep].visits += Number(d.visits ?? 0);
    sums[rep].prospect += Number(d.prospect ?? 0);
  }
  const rows = Object.values(sums).map(r => ({ week_start: input.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const lines = rows.map(r => '| ' + r.rep + ' | ' + r.visits + ' | ' + r.prospect + ' |');
  const table = ['| 担当者 | 訪問件数 | 見込み額 |', '|---|---|---|', ...lines].join('\n');
  return { rows: rows, table: table };
}

