function main(input) {
  const q = (s) => '"' + String(s == null ? '' : s).replace(/"/g, '""') + '"';
  const items = (input.items || [])
    .map(x => ({ code: x.data.code, name: x.data.name, qty: Number(x.data.qty), rp: Number(x.data.reorder_point), order_qty: Number(x.data.reorder_qty) }))
    .filter(x => x.qty < x.rp)
    .map(x => ({ code: x.code, name: x.name, order_qty: x.order_qty }));
  const lines = ['品番,品名,発注数'].concat(items.map(x => [q(x.code), q(x.name), q(x.order_qty)].join(',')));
  return { items: items, csv: lines.join('\r\n') + '\r\n' };
}

function main(input) {
  const rows = (input.items || []).map(function (r) {
    return { code: (r.data && r.data.code) || '', borrower: (r.data && r.data.borrower) || '', due: (r.data && r.data.due_on) || '' };
  });
  rows.sort(function (a, b) { return a.due < b.due ? -1 : (a.due > b.due ? 1 : 0); });
  let md = '# 延滞一覧（' + input.date + ' 時点）\n\n';
  md += '対象: ' + rows.length + ' 件\n\n';
  if (rows.length === 0) {
    md += '延滞はありません。\n';
  } else {
    md += '| 管理番号 | 借りた人 | 返却予定日 |\n|---|---|---|\n';
    for (const r of rows) {
      md += '| ' + r.code + ' | ' + r.borrower + ' | ' + r.due + ' |\n';
    }
  }
  return { markdown: md };
}

function main(input: any) {
  const norm = (s: string) => (s ?? '').normalize('NFKC').toLowerCase().replace(/[\s、。！？!?,.・「」『』（）()]/g, '');
  const grams = (s: string) => { const arr: string[] = []; for (let i = 0; i + 1 < s.length; i++) { const g = s.slice(i, i + 2); if (arr.indexOf(g) < 0) arr.push(g); } return arr; };
  const qg = grams(norm(input.question));
  let best: any = null; let bestScore = 0;
  for (const it of (input.items ?? [])) {
    const fg = grams(norm(it.data?.question));
    if (fg.length === 0) continue;
    let hit = 0;
    for (const g of fg) { if (qg.indexOf(g) >= 0) hit++; }
    const score = hit / fg.length;
    if (score > bestScore) { bestScore = score; best = it; }
  }
  if (best && bestScore >= 0.6) {
    return { matched: true, score: bestScore, faq_no: String(best.data.faq_no ?? ''), question: String(best.data.question ?? ''), answer: String(best.data.answer ?? '') };
  }
  return { matched: false, score: bestScore, faq_no: '', question: '', answer: '' };
}
