function main(input) {
  const r = Number(input.responses);
  const p = Number(input.promoters);
  const d = Number(input.detractors);
  if (!(r > 0)) throw new Error('回答数が 0 のため NPS を計算できません');
  const raw = (p - d) / r * 100;
  const nps = Math.sign(raw) * Math.round(Math.abs(raw));
  return { responses: r, promoters: p, detractors: d, nps: nps };
}
